function countBalancingRemovals(nums: number[]): number {
  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    const rest = [...nums.slice(0, i), ...nums.slice(i + 1)];
    let even = 0, odd = 0;
    rest.forEach((x, j) => { if (j % 2 === 0) even += x; else odd += x; });
    if (even === odd) count++;
  }
  return count;
}

