    def countBalancingRemovals(self, nums: List[int]) -> int:
        count = 0
        for i in range(len(nums)):
            rest = nums[:i] + nums[i + 1:]
            if sum(rest[0::2]) == sum(rest[1::2]):
                count += 1
        return count

