function countBalancingRemovals(nums: number[]): number {
  let evenAhead = 0, oddAhead = 0;
  nums.forEach((x, i) => { if (i % 2 === 0) evenAhead += x; else oddAhead += x; });
  let evenBefore = 0, oddBefore = 0, count = 0;
  for (let i = 0; i < nums.length; i++) {
    if (i % 2 === 0) evenAhead -= nums[i]; else oddAhead -= nums[i];
    // after the deletion, the suffix swaps parity
    if (evenBefore + oddAhead === oddBefore + evenAhead) count++;
    if (i % 2 === 0) evenBefore += nums[i]; else oddBefore += nums[i];
  }
  return count;
}

